create or replace function public.manage_stream_comment(_school uuid,_post uuid,_comment uuid,_body text,_action text,_reason text,_actor uuid) returns public.classroom_stream_comments language plpgsql security definer set search_path='' as $$
declare _row public.classroom_stream_comments;_classroom uuid;_teacher boolean;begin select classroom_id into _classroom from public.classroom_stream_posts where school_id=_school and id=_post and status='published';if _classroom is null then raise exception 'Post unavailable.' using errcode='P0002';end if;_teacher:=public.can_edit_classroom(_school,_classroom,_actor);
if _action='create' then if not exists(select 1 from public.learning_classroom_memberships where school_id=_school and classroom_id=_classroom and active and (user_id=_actor or student_id in(select id from public.students where user_id=_actor))) then raise exception 'Not a classroom member.' using errcode='42501';end if;insert into public.classroom_stream_comments(school_id,post_id,body,status,author_id) values(_school,_post,trim(_body),case when _teacher then 'published' else 'pending' end,_actor) returning * into _row;
else if not _teacher then raise exception 'Moderation permission required.' using errcode='42501';end if;update public.classroom_stream_comments set status=case _action when 'approve' then 'published' when 'hide' then 'hidden' else 'removed' end,moderated_by=_actor,moderation_reason=trim(_reason) where school_id=_school and id=_comment and post_id=_post returning * into _row;end if;return _row;end$$;
revoke all on function public.manage_stream_comment(uuid,uuid,uuid,text,text,text,uuid) from public,anon,authenticated;grant execute on function public.manage_stream_comment(uuid,uuid,uuid,text,text,text,uuid) to service_role;
